          RefreshLayout({
            loading: this.vm.isLoading,
            isEnableSlideUp: this.vm.hasMore,
            scroller: this.gridScroller,
            onRefresh: (direction: "pull" | "slideUp"): void => {
              if (direction === "pull") { this.vm.onRefresh(); } else { this.vm.onLoadMore(); }
